   853	NCPInstanceBase::on_mesh_prefix_was_added(Origin origin, const struct in6_addr &prefix_address, uint8_t prefix_len,
   854	        uint8_t flags, bool stable, uint16_t rloc16, CallbackWithStatus cb)
   855	{
   856	        IPv6Prefix prefix(prefix_address, prefix_len);
   857	        OnMeshPrefixEntry entry(origin, flags, stable, rloc16);
   858	        std::multimap<IPv6Prefix, OnMeshPrefixEntry>::iterator iter;
   859	
   860	        iter = find_prefix_entry(prefix, entry);
   861	
   862	        if (iter == mOnMeshPrefixes.end()) {
   863	                mOnMeshPrefixes.insert(std::make_pair(prefix, entry));
   864	                syslog(LOG_INFO, "OnMeshPrefixes: Adding %s", entry.get_description(prefix).c_str());
   865	
   866	                if (origin != kOriginThreadNCP) {
   867	                        add_on_mesh_prefix_on_ncp(prefix.get_prefix(), prefix.get_length(), flags, stable,
   868	                                boost::bind(&NCPInstanceBase::check_ncp_entry_update_status, this, _1, "adding on-mesh prefix", cb));
   869	                } else {
   870	                        cb(kWPANTUNDStatus_Ok);
   871	                }
   872	        } else {
   873	                cb(kWPANTUNDStatus_Ok);
   874	        }
   875	
   876	        if (entry.is_on_mesh() && entry.is_slaac() && prefix.get_length() == kSLAACPrefixLength
   877	                && !has_address_with_prefix(prefix)
   878	        ) {
   879	                struct in6_addr address = make_slaac_addr_from_eui64(prefix.get_prefix().s6_addr, mMACAddress);
   880	                syslog(LOG_NOTICE, "Pushing a new SLAAC address %s/%d to NCP", in6_addr_to_string(address).c_str(), prefix_len);
   881	                add_unicast_address_on_ncp(address, prefix_len,
   882	                        boost::bind(&NCPInstanceBase::check_ncp_entry_update_status, this, _1, "adding SLAAC address", NilReturn()));
   883	                // Note that SLAAC address is added with origin NCP independent of the origin of the prefix.
   884	                unicast_address_was_added(kOriginThreadNCP, address, prefix_len);
   885	        }
   886	}
